int write_register_data(struct task_struct *child, addr_t addr, addr_t data) {
    if (!child || (addr & 0x3) || (addr >= 0x1000)) {
        return -EINVAL;
    }

    switch (addr) {
        case PSW_ADDR: {
            if ((data & PSW_RESERVED_MASK) != 0) {
                return -EINVAL;
            }
            child->thread.psw = data;
            break;
        }

        case GPR_ADDR_BASE ... GPR_ADDR_TOP: {
            int reg_index = addr - GPR_ADDR_BASE;
            if (reg_index < 0 || reg_index >= 16) {
                return -EINVAL;
            }
            child->thread.gprs[reg_index] = data;
            break;
        }

        case ACR_ADDR_BASE ... ACR_ADDR_TOP: {
            int acr_index = addr - ACR_ADDR_BASE;
            if (acr_index < 0 || acr_index >= 16) {
                return -EINVAL;
            }
            child->thread.acrs[acr_index] = data;
            break;
        }

        case FPR_ADDR_BASE ... FPR_ADDR_TOP: {
            int fpr_index = addr - FPR_ADDR_BASE;
            if (fpr_index < 0 || fpr_index >= 16) {
                return -EINVAL;
            }
            child->thread.fprs[fpr_index] = *(freg_t *)&data;
            break;
        }

        default: {
            if ((addr & 0xff00) == 0x200) {
                if (data & 0x1) {
                    return -EINVAL;
                }
                handle_special_case(child, addr, data);
            } else {
                return -EINVAL;
            }
            break;
        }
    }

    return 0;
}

int write_register_data(struct task_struct *child, addr_t addr, addr_t data) {
    void *regs = child->thread.regs;

    if (!regs)
        return -EINVAL;

    if (addr >= sizeof(struct psw) && addr < sizeof(struct psw) + 16 * sizeof(addr_t)) {
        int reg_idx = (addr - sizeof(struct psw)) / sizeof(addr_t);
        if (reg_idx < 0 || reg_idx >= 16)
            return -EINVAL;
        ((addr_t *)regs)[sizeof(struct psw) / sizeof(addr_t) + reg_idx] = data;
    } else if (addr >= sizeof(struct psw) + 16 * sizeof(addr_t) && addr < sizeof(struct psw) + 16 * sizeof(addr_t) + 16 * sizeof(addr_t)) {
        int acr_idx = (addr - sizeof(struct psw) - 16 * sizeof(addr_t)) / sizeof(addr_t);
        if (acr_idx < 0 || acr_idx >= 16)
            return -EINVAL;
        ((addr_t *)regs)[(sizeof(struct psw) + 16 * sizeof(addr_t)) / sizeof(addr_t) + acr_idx] = data & 0xFFFF;
    } else if (addr >= sizeof(struct psw) + 32 * sizeof(addr_t) && addr < sizeof(struct psw) + 32 * sizeof(addr_t) + 16 * sizeof(addr_t)) {
        int fpr_idx = (addr - sizeof(struct psw) - 32 * sizeof(addr_t)) / sizeof(addr_t);
        if (fpr_idx < 0 || fpr_idx >= 16)
            return -EINVAL;
        ((addr_t *)regs)[(sizeof(struct psw) + 32 * sizeof(addr_t)) / sizeof(addr_t) + fpr_idx] = data;
    } else {
        switch (addr) {
            case 0:
                ((struct psw *)regs)->mask = data & PSW_MASK;
                ((struct psw *)regs)->addr = data & PSW_ADDR;
                break;
            default:
                return -EINVAL;
        }
    }

    return 0;
}

#include <linux/errno.h>

int write_register_data(struct task_struct *child, addr_t addr, addr_t data) {
    if (!child || addr == (addr_t)NULL) {
        return -EINVAL;
    }

    if ((addr >= PSW_REGISTER_OFFSET && addr < PSW_REGISTER_OFFSET + sizeof(psw_t)) ||
        (addr >= GPR_REGISTER_OFFSET && addr < GPR_REGISTER_OFFSET + GPR_REGISTER_SIZE)) {
        // Valid register address range
        void *target_register = (void *)((char *)child + addr);
        *(addr_t *)target_register = data;
    } else if (addr >= ACR_REGISTER_OFFSET && addr < ACR_REGISTER_OFFSET + ACR_REGISTER_SIZE) {
        // Access register validation
        if (data > 0xFFFF) {
            return -EINVAL;
        }
        void *acr_register = (void *)((char *)child + addr);
        *(addr_t *)acr_register = data;
    } else if (addr >= FPR_REGISTER_OFFSET && addr < FPR_REGISTER_OFFSET + FPR_REGISTER_SIZE) {
        // Floating-point register handling
        if (data > 0xFFFFFFFFFFFFFFFF) {
            return -EINVAL;
        }
        void *fpr_register = (void *)((char *)child + addr);
        *(addr_t *)fpr_register = data;
    } else {
        return -EINVAL;
    }

    return 0;
}

int write_register_set(struct task_struct *child, addr_t addr, addr_t data)
{
    if (!child || !access_ok(VERIFY_WRITE, addr, sizeof(addr_t)))
        return -EINVAL;

    if (addr >= PSW_OFFSET && addr < PSW_OFFSET + sizeof(psw_t)) {
        psw_t *psw = (psw_t *)((char *)child->thread.psw + (addr - PSW_OFFSET));
        if (data & PSW_RESERVED_MASK)
            return -EINVAL;
        *psw = (psw_t)data;
    } else if (addr >= GPR_OFFSET && addr < GPR_OFFSET + (NUM_GPRS * sizeof(gpr_t))) {
        int reg = (addr - GPR_OFFSET) / sizeof(gpr_t);
        if (reg < 0 || reg >= NUM_GPRS)
            return -EINVAL;
        ((gpr_t *)((char *)&child->thread.gpr))[reg] = (gpr_t)data;
    } else if (addr >= ACR_OFFSET && addr < ACR_OFFSET + (NUM_ACRS * sizeof(acr_t))) {
        int acr = (addr - ACR_OFFSET) / sizeof(acr_t);
        if (acr < 0 || acr >= NUM_ACRS)
            return -EINVAL;
        ((acr_t *)((char *)&child->thread.acr))[acr] = (acr_t)data;
    } else if (addr >= FPR_OFFSET && addr < FPR_OFFSET + (NUM_FPRS * sizeof(fpr_t))) {
        int fpr = (addr - FPR_OFFSET) / sizeof(fpr_t);
        if (fpr < 0 || fpr >= NUM_FPRS)
            return -EINVAL;
        ((fpr_t *)((char *)&child->thread.fpr))[fpr] = *(fpr_t *)&data;
    } else {
        return -EINVAL;
    }

    return 0;
}

int write_register(struct task_struct *child, addr_t addr, addr_t data) {
    if (!child || addr >= REGISTER_AREA_SIZE)
        return -EINVAL;

    if (addr >= PSW_OFFSET && addr < PSW_OFFSET + sizeof(psw_t)) {
        psw_t *psw = (psw_t *)((char *)child->regs + addr);
        if (data & ~PSW_VALID_MASK)
            return -EINVAL;
        *psw = (psw_t)data;
    } else if (addr >= GPR_OFFSET && addr < GPR_OFFSET + GPR_AREA_SIZE) {
        if (addr % sizeof(addr_t) != 0)
            return -EINVAL;
        if (data & ~GPR_VALID_MASK)
            return -EINVAL;
        *(addr_t *)((char *)child->regs + addr) = data;
    } else if (addr >= ACR_OFFSET && addr < ACR_OFFSET + ACR_AREA_SIZE) {
        if (addr % sizeof(acr_t) != 0)
            return -EINVAL;
        if (data & ~ACR_VALID_MASK)
            return -EINVAL;
        *(acr_t *)((char *)child->regs + addr) = (acr_t)data;
    } else if (addr >= FPR_OFFSET && addr < FPR_OFFSET + FPR_AREA_SIZE) {
        if (addr % sizeof(fpr_t) != 0)
            return -EINVAL;
        *(fpr_t *)((char *)child->regs + addr) = *(fpr_t *)&data;
    } else {
        return -EINVAL;
    }

    return 0;
}
